'use strict';
(()=>{
  const J=ByeByeJourney,P=J.P,C=J.C,$=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)],escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const store=J.createStore({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)});
  const state={view:'welcome',step:1,p:J.defaults(),matches:[],selected:null,editReview:false,started:false,drafts:new Map(),directoryRegion:'any',directorySearch:'',directorySort:'popular',directoryLimit:18,returnView:'welcome'};
  const main=$('#main'),dialog=$('#info-dialog'),arrow='<span class="arrow" aria-hidden="true">→</span>';
  const normal=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const money=(n,p=state.p,precise=false)=>C.money(n,p.currency,precise),date=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s+'T12:00:00'));
  const airportName=code=>P.origins[code]||code;
  const popularCountries=[...P.countries].sort((a,b)=>a.popular-b.popular||a.name.localeCompare(b.name));
  const countries=(region='any')=>popularCountries.filter(c=>P.inRegion(c,region));
  const countText=p=>`${p.adults} adult${p.adults===1?'':'s'}${p.children.length?` + ${p.children.length} child${p.children.length===1?'':'ren'}`:''}`;
  function credit(d){return d?`<p class="image-credit">Photo: <a href="${escape(d.source)}" target="_blank" rel="noopener noreferrer">${escape(d.credit)}</a>${d.license?` · ${d.licenseUrl?`<a href="${escape(d.licenseUrl)}" target="_blank" rel="noopener noreferrer">${escape(d.license)}</a>`:escape(d.license)}`:''} · Cropped to fit</p>`:'';}
  function icon(name){const paths={beach:'M3 16h18M6 16c0-5 3-9 6-12 3 3 6 7 6 12M12 4v17M3 16c0-6 4-12 9-12s9 6 9 12',city:'M4 21V8h7v13M11 21V3h9v18M7 11v1m0 4v1m7-10h2m-2 4h2m-2 4h2M2 21h20',nature:'m12 3-7 9h4l-5 6h7v4h2v-4h7l-5-6h4z',culture:'m3 9 9-6 9 6H3m2 3v7m5-7v7m4-7v7m5-7v7M3 21h18',adventure:'m2 20 7-13 4 7 3-5 6 11H2m5-9 2 2 2-2',relaxation:'M3 12c4 0 5 6 9 6s5-6 9-6M3 9v12M21 9v12M8 4h.01M12 3h.01M16 4h.01',food:'M5 3v7m4-7v7m-2 0v11M3 3v5a4 4 0 0 0 8 0V3M19 3c-4 2-4 8 0 9v9m0-18v9',nightlife:'M5 3h14l-7 9L5 3m7 9v9m-5 0h10',any:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3',solo:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M5 21v-2a7 7 0 0 1 14 0v2',couple:'M7 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6m10 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6M2 21v-3a5 5 0 0 1 10 0v3m0-3a5 5 0 0 1 10 0v3',friends:'M12 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6M7 21v-5a5 5 0 0 1 10 0v5M3 10h1m16 0h1M2 21v-5h2m16 0h2v5',family:'M7 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6m10 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6M2 21v-7h4m12 0h4v7m-10-5a2 2 0 1 0 0-4 2 2 0 0 0 0 4m-3 5v-2a3 3 0 0 1 6 0v2',budget:'M3 20V8h18v12M3 16h18M6 8V5h12v3M6 12h4m4 0h4',comfortable:'M4 21V5h16v16M8 9h2m4 0h2M8 13h2m4 0h2m-5 8v-4h2v4',boutique:'M4 21V7l8-4 8 4v14M9 21v-6h6v6M8 10h1m6 0h1',luxury:'m3 7 4 5 5-8 5 8 4-5-2 13H5L3 7',balanced:'M4 7h16M4 17h16M8 4v6m8 4v6',packed:'m13 2-9 12h7l-1 8 10-13h-7z',local:'M4 4h16v5H4zM6 9v12m12-12v12M9 14h6',vegetarian:'M20 3C8 3 3 8 5 15c3 7 14 6 15-12M5 20 16 9',vegan:'M20 3C8 3 3 8 5 15c3 7 14 6 15-12M5 20 16 9',halal:'M18 4a8 8 0 1 0 2 14A9 9 0 0 1 18 4',seafood:'M5 12c5-9 12-9 16 0-4 9-11 9-16 0m0 0L2 8v8l3-4m11-2h.01'};return `<span class="choice-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[name]||paths.any}"/></svg></span>`;}
  function choice(key,value,label,description='',glyph=value,wide=false){const selected=key==='interests'?state.p.interests.includes(value):state.p[key]===value;return `<button type="button" class="choice-card ${wide?'full-width':''}" data-choice="${key}" data-value="${value}" aria-label="${escape(label)}" aria-description="${escape(description)}" aria-pressed="${selected}">${icon(glyph)}<span><strong>${escape(label)}</strong>${description?`<small style="display:block;margin-top:5px">${escape(description)}</small>`:''}</span></button>`;}
  function announce(text){$('#announcements').textContent=text;}
  function savedCount(){$('#saved-count').textContent=store.list().length;}
  function go(view,{step=state.step,push=true,focus=true}={}){state.view=view;state.step=step;render();if(push)history.pushState({byebye:true,view,step,selected:state.selected},'',view==='question'?`#step-${step}`:`#${view}`);if(focus){window.scrollTo({top:0,behavior:'instant'});$('h1',main)?.focus({preventScroll:true});}}
  window.addEventListener('popstate',e=>{if(e.state?.byebye){state.selected=e.state.selected||state.selected;go(e.state.view,{step:e.state.step,push:false});}else go('welcome',{push:false});});
  function showDialog(title,body){$('#dialog-content').innerHTML=`<h2 id="dialog-title">${escape(title)}</h2>${body}`;dialog.showModal();}
  $('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  function welcome(){const d=J.destination('palawan');return `<section class="welcome fade-in"><div class="welcome-copy"><p class="eyebrow">A little less planning. A lot more going.</p><h1 tabindex="-1">Where will<br>your budget<br><em>take you?</em></h1><p class="welcome-lead">Big adventure or little escape. Find a trip that feels like you, at a price that works for you.</p><button class="primary" data-action="start">${state.started?'Continue planning':'Find my next trip'} ${arrow}</button><div class="welcome-trust"><span>No sign-up</span><span>Your budget, your choice</span></div><div class="welcome-bottom"><p><strong>250</strong>countries & territories</p><p><strong>160</strong>currencies to plan in</p><p><strong>Yours.</strong>Every little detail.</p></div></div><div class="welcome-visual"><figure><img src="${escape(d.image)}" alt="${escape(d.caption||'Limestone cliffs and lagoons in Palawan, Philippines')}" fetchpriority="high"><figcaption><p class="eyebrow">A LITTLE INSPIRATION</p><h2>Somewhere like Palawan.</h2><p>Lagoons, limestone & a slower kind of day.</p></figcaption></figure><div class="travel-stamp" aria-hidden="true">Made for<span>↗</span>your kind of trip</div>${credit(d)}</div></section>`;}
  const steps=[null,
    ['Your budget','What’s your total trip budget?','One budget for everyone travelling. Flights, stays, food, and the good stuff in between.','lisbon'],
    ['Flying from','Where does your trip begin?','Choose your country, then the airport that works for you.','sydney'],
    ['Your travel dates','When’s your next escape?','Pick a departure date and how long you’d like to stay.','palawan'],
    ['Your travel group','Who’s coming along?','A solo adventure, a shared escape, or the whole family.','vancouver'],
    ['Your ideal escape','What’s your kind of getaway?','Pick everything that sounds like you. There’s no wrong combination.','banff'],
    ['Your destination','Where are you drawn to?','Stay open to anywhere, or point us in a direction.','kyoto'],
    ['Your travel pace','How do you like to spend a day?','An empty afternoon can be just as good as a full itinerary.','split'],
    ['Food preferences','What’s on your menu?','Tell us your preference. You’ll confirm ingredients and availability with restaurants.','bangkok'],
    ['Your accommodation','Where would you love to stay?','A comfortable base for your kind of adventure.','marrakech'],
    ['One last look','Does this feel like your trip?','Your preferences, all in one place. Change anything before we find your match.','palawan']];
  function question(){const p=state.p,step=state.step,[title,heading,description,image]=steps[step],d=J.destination(image);return `<section class="journey-layout ${step===10?'review-layout':''} fade-in"><div class="question-panel"><div class="journey-progress"><strong>${escape(title)}</strong><span>${String(step).padStart(2,'0')} / 10</span></div><div class="progress-track" role="progressbar" aria-label="Trip planning progress" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${step}"><span style="width:${step*10}%"></span></div><div class="question-heading"><p class="eyebrow">LET’S MAKE IT YOURS</p><h1 tabindex="-1">${heading}</h1><p>${description}</p></div><div class="question-content" id="question-content">${stepContent(step)}<p class="error-message" id="step-error" role="alert" hidden></p></div><div class="journey-actions"><button class="back-button" data-action="back"><span aria-hidden="true">←</span> Back</button><button class="primary" data-action="continue">${step===10?'Find my destination':state.editReview?'Save & review':'Continue'} ${arrow}</button></div></div><aside class="question-image" aria-label="Travel inspiration"><figure><img src="${escape(d.image)}" alt="${escape(d.caption||d.city+', '+d.country)}"><span class="photo-location">${escape(d.city)}, ${escape(d.country)}</span><figcaption><h3>${escape(d.tagline||d.badge)}</h3><p>Your next chapter could start here.</p></figcaption></figure>${credit(d)}</aside></section>`;}
  function currencyOptions(q=''){const top=['EUR','USD','GBP','CAD','AUD','JPY','CNY','KRW','THB','PHP','AED','SAR','QAR','JOD','INR'],list=[...top,...C.codes.filter(c=>!top.includes(c)).sort((a,b)=>C.name(a).localeCompare(C.name(b)))];return list.filter(c=>!q||normal(`${c} ${C.name(c)}`).includes(normal(q))||c===state.p.currency).map(c=>`<option value="${c}" ${c===state.p.currency?'selected':''}>${c} · ${escape(C.name(c))}</option>`).join('');}
  function airportOptions(list,selected,q=''){const filtered=list.filter(a=>normal(`${a.code} ${a.city} ${a.name}`).includes(normal(q)));const current=list.find(a=>a.code===selected),display=current&&!filtered.includes(current)?[current,...filtered]:filtered;return {html:display.map(a=>`<option value="${a.code}" ${a.code===selected?'selected':''}>${escape(`${a.code} · ${a.city||a.name} — ${a.name}`)}</option>`).join('')||'<option value="">No airports listed</option>',count:filtered.length};}
  function departureChoices(){return [...P.airports,...P.legacyOriginAirports].filter(a=>a.country===state.p.originCountry);}
  function counter(key,title,hint,value,min,max){return `<div class="counter-row"><div><strong>${title}</strong><p>${hint}</p></div><div class="counter"><button type="button" data-counter="${key}" data-delta="-1" aria-label="Fewer ${title.toLowerCase()}" ${value<=min?'disabled':''}>−</button><output aria-label="${title}">${value}</output><button type="button" data-counter="${key}" data-delta="1" aria-label="More ${title.toLowerCase()}" ${value>=max?'disabled':''}>+</button></div></div>`;}
  function groupControls(){const p=state.p;return `${counter('adults','Adults','Ages 18+',p.adults,1,9-p.children.length)}${p.groupType==='family'?counter('children','Children','Ages 0–17 on the return date',p.children.length,0,9-p.adults):''}${p.children.map((c,i)=>`<div class="child-row"><div class="child-name">Child ${i+1}</div><div class="field"><label for="child-age-${i}">Age on return date</label><select id="child-age-${i}" data-child-age="${i}"><option value="">Choose age</option>${Array.from({length:18},(_,age)=>`<option value="${age}" ${c.age===age?'selected':''}>${age===0?'Under 1 year':`${age} year${age===1?'':'s'}`}</option>`).join('')}</select></div>${c.age!==null&&c.age<2?`<div class="field" style="grid-column:1/-1"><label for="infant-seat-${i}">Infant seating</label><select id="infant-seat-${i}" data-infant-seat="${i}"><option value="lap" ${c.seat==='lap'?'selected':''}>On an adult’s lap</option><option value="seat" ${c.seat==='seat'?'selected':''}>Own seat</option></select></div>`:''}</div>`).join('')}${counter('rooms','Rooms','Adjust to suit your group',p.rooms,1,p.adults)}<p class="field-hint">Up to 9 travellers. Airlines count ages 12–17 as adults; hotels receive their actual ages. Check each provider’s age and room rules.</p>`;}
  function stepContent(step){const p=state.p;
    if(step===1)return `<div class="field"><label for="currency-search">Search currencies</label><input id="currency-search" type="search" placeholder="Euro, dollar, AED…" autocomplete="off" aria-controls="currency"></div><div class="field"><label for="currency">Your currency</label><select id="currency">${currencyOptions()}</select></div><label class="field-label" for="budget-amount">Total for your whole group</label><div class="amount-field"><span id="currency-symbol" aria-hidden="true">${escape(C.symbol(p.currency))}</span><input id="budget-amount" type="number" min="0.01" step="any" inputmode="decimal" value="${J.round(p.budget*C.rate(p.currency))}" aria-describedby="budget-hint"></div><div class="presets" role="group" aria-label="Budget presets">${[1000,2000,3500,5000].map(n=>`<button class="chip" data-budget="${n}">${escape(C.format(n,p.currency))}</button>`).join('')}</div><p class="field-hint" id="budget-hint">For everyone, for the whole trip — not per person.</p><p class="field-hint">Exchange rates: ${C.date}. ${Math.floor((Date.now()-new Date(C.date))/86400000)>3?'Using an older saved snapshot. ':''}Provider and bank rates may differ.</p>`;
    if(step===2){const list=departureChoices(),options=airportOptions(list,p.origin);return `<div class="field"><label for="origin-country-search">Search departure countries</label><input id="origin-country-search" type="search" placeholder="Country or territory" autocomplete="off" aria-controls="origin-country"></div><div class="field"><label for="origin-country">Departure country or territory</label><select id="origin-country">${popularCountries.map(c=>`<option value="${c.code}" ${p.originCountry===c.code?'selected':''}>${escape(c.name)}</option>`).join('')}</select></div><div class="field"><label for="origin-search">Find your airport</label><input id="origin-search" type="search" placeholder="City, airport name, or code" autocomplete="off" aria-controls="origin-airport"></div><div class="field"><label for="origin-airport">Departure airport</label><select id="origin-airport" ${list.length?'':'disabled'}>${options.html}</select><p class="field-hint" id="origin-status" role="status">${list.length?`${list.length} airports · popular choices first`:'No passenger airports listed here. Choose a nearby country and an airport you can reach.'}</p></div>`;}
    if(step===3)return `<div class="field"><label for="departure">Departure date</label><input id="departure" type="date" value="${escape(p.departure)}" min="${J.dateKey(new Date())}" required></div><div class="field"><label for="nights">How many nights?</label><input id="nights" type="number" min="1" max="30" step="1" inputmode="numeric" value="${p.nights}"></div><div class="presets" role="group" aria-label="Suggested trip lengths">${[3,5,7,10,14].map(n=>`<button class="chip" aria-pressed="${p.nights===n}" data-nights="${n}">${n} nights</button>`).join('')}</div><div class="note" id="date-summary">${dateSummary()}</div><p class="field-hint">Hotel dates start on your departure date. For overnight flights, adjust check-in with the provider after choosing your flight.</p>`;
    if(step===4)return `<div class="selection-grid" role="group" aria-label="Travel group">${choice('groupType','solo','Solo','A little time for you.')}${choice('groupType','couple','Couple','Better together.')}${choice('groupType','friends','Friends','Good company. New memories.')}${choice('groupType','family','Family','An adventure for everyone.')}</div><div id="group-controls" class="group-controls">${groupControls()}</div>`;
    if(step===5)return `<div class="selection-grid compact" role="group" aria-label="Escape styles">${Object.entries(J.interests).map(([key,label])=>choice('interests',key,label,'',key,key==='any')).join('')}</div><p class="field-hint" id="interest-count">${p.interests[0]==='any'?'Open to a little of everything.':`${p.interests.length} style${p.interests.length===1?'':'s'} selected`}</p>`;
    if(step===6)return `<div class="selection-grid compact" role="group" aria-label="Destination regions">${J.regions.map(region=>choice('region',region,region==='any'?'Anywhere':region,'','any')).join('')}</div><div class="field" style="margin-top:23px"><label for="destination-country">Have a country in mind? <span class="field-hint">Optional</span></label><input id="destination-country" type="search" list="destination-countries" placeholder="Anywhere — or type a country" value="${p.country==='any'?'':escape(P.countries.find(c=>c.code===p.country)?.name)}" autocomplete="off"><datalist id="destination-countries">${countries(p.region).map(c=>`<option value="${escape(c.name)}">${escape(c.continent)}</option>`).join('')}</datalist></div><button class="text-button" data-action="directory">Browse all 250 countries & territories</button>`;
    if(step===7)return `<div class="choice-list" role="group" aria-label="Travel pace">${choice('pace','relaxed','Relaxed','Slow mornings, one main outing, room to unwind.','relaxation')}${choice('pace','balanced','Balanced','A little exploring. A little doing nothing.','balanced')}${choice('pace','packed','Packed with activities','Early starts, full days, plenty to discover.','packed')}</div>`;
    if(step===8)return `<div class="selection-grid" role="group" aria-label="Food preference">${Object.entries(J.foods).map(([key,label])=>choice('food',key,label,'',key)).join('')}</div><div class="note">These are preferences, not verified restaurant options. Confirm ingredients, preparation, and dietary needs with each restaurant.</div>`;
    if(step===9)return `<div class="choice-list" role="group" aria-label="Accommodation style">${choice('stay','budget','Budget stay','Simple, good-value places. More for the adventure.')}${choice('stay','comfortable','Comfortable hotel','A dependable base with everyday comforts.')}${choice('stay','boutique','Boutique stay','Smaller stays with a little local character.')}${choice('stay','luxury','Luxury','More space, extra comfort, and special touches.')}</div>`;
    return review();
  }
  function dateSummary(){try{return `${date(state.p.departure)} → ${date(J.returnDate(state.p))} · ${state.p.nights} nights`;}catch{return 'Choose a departure date and trip length.';}}
  function review(){const p=state.p,items=[['Budget',`${money(p.budget)} ${p.currency} · whole group`],['Flying from',`${airportName(p.origin)} · ${P.countries.find(c=>c.code===p.originCountry)?.name||''}`],['Travel dates',dateSummary()],['Travel group',`${countText(p)} · ${p.rooms} room${p.rooms===1?'':'s'}${p.children.length?' · children: '+p.children.map(c=>`${c.age}y${c.age<2?' ('+c.seat+')':''}`).join(', '):''}`],['Ideal escape',p.interests.map(i=>J.interests[i]).join(', ')],['Destination',p.country!=='any'?P.countries.find(c=>c.code===p.country)?.name:p.region==='any'?'Anywhere':p.region],['Travel pace',J.paces[p.pace]],['Food',J.foods[p.food]],['Accommodation',J.stays[p.stay]]];return `<dl class="review-list">${items.map(([label,value],i)=>`<div class="review-row"><div><dt>${label}</dt><dd>${escape(value)}</dd></div><button data-edit="${i+1}" aria-label="Edit ${label.toLowerCase()}">Edit</button></div>`).join('')}</dl><div class="note">Your match comes with planning estimates where available. You’ll check current prices with booking providers.</div>`;}
  function showError(message){const target=$('#step-error');if(target){target.hidden=false;target.textContent=message;target.scrollIntoView({block:'nearest',behavior:'instant'});}announce(message);}
  function countryCode(value){const q=normal(value),aliases={usa:'US',us:'US',america:'US',uk:'GB',uae:'AE',korea:'KR','south korea':'KR',holland:'NL'};return !q?'any':aliases[q]||P.countries.find(c=>normal(c.name)===q||normal(c.code)===q||c.aliases?.some(a=>normal(a)===q))?.code||'invalid';}
  function syncFields(){const p=state.p;
    if(state.view!=='question')return;
    if(state.step===1)p.budget=$('#budget-amount').value===''?NaN:Number($('#budget-amount').value)/C.rate(p.currency);
    if(state.step===2){p.originCountry=$('#origin-country').value;p.origin=$('#origin-airport').value;}
    if(state.step===3){p.departure=$('#departure').value;p.nights=Number($('#nights').value);}
    if(state.step===6)p.country=countryCode($('#destination-country').value);
  }
  function continueJourney(){syncFields();if(state.step===10){try{state.p=J.validate(state.p);state.matches=J.recommend(state.p);state.selected=state.matches[0]?.destination.id;state.editReview=false;go('reveal');}catch(e){state.editReview=true;go('question',{step:e.step||1});showError(e.message);}return;}const error=J.validateStep(state.p,state.step);if(error){showError(error);return;}const next=state.editReview?10:state.step+1;state.editReview=false;go('question',{step:next});}
  function draftKey(d,p=state.p){return JSON.stringify([d.id,p.origin,p.departure,p.nights,p.adults,p.children,p.rooms,p.pace,p.food,p.stay]);}
  function getDraft(d,p=state.p){const key=draftKey(d,p);if(!state.drafts.has(key))state.drafts.set(key,{values:J.initialCosts(d,p),edited:false});return state.drafts.get(key);}
  function costSummary(d){const draft=getDraft(d),c=J.calculate(draft.values,state.p),ready=c.status==='ready',labels={flights:'Return flights',accommodation:'Accommodation',food:'Food',transport:'Transport',activities:'Activities',extras:'Extras'},description=ready?`${J.count(state.p)} traveller${J.count(state.p)===1?'':'s'} · ${state.p.nights} nights${draft.edited?' · based on your entries':' · illustrative amounts'}`:`${c.status==='invalid'?'Check the amounts in your calculator.':'Add the missing prices in your calculator.'} The full trip total is not yet known.`;return `<p class="cost-label">${draft.edited?'YOUR PERSONAL ESTIMATE':'ILLUSTRATIVE PLANNING ESTIMATE'}</p><output class="total ${ready?'':'incomplete'}" id="trip-total">${ready?money(c.total,state.p,true):'Estimate incomplete'}</output><p class="total-description">${description}</p><div id="budget-status" class="budget-status ${ready?c.withinBudget?'':'over':'incomplete'}">${ready?c.withinBudget?`${money(c.remaining,state.p,true)} left in your budget`:`${money(-c.remaining,state.p,true)} above your budget`:'Budget fit not yet assessed'}</div><dl class="breakdown">${Object.entries(c.parts).map(([key,value])=>`<div><dt>${labels[key]}</dt><dd class="${value===null?'unknown':''}">${value===null?'Add price':money(value,state.p,true)}</dd></div>`).join('')}<div><dt>Extra allowance (${escape(draft.values.buffer)}%)</dt><dd>${c.buffer===null?'Pending':money(c.buffer,state.p,true)}</dd></div>${!ready?`<div><dt>Known costs only</dt><dd>${money(c.subtotal,state.p,true)}</dd></div>`:''}</dl><p class="cost-footnote">Budget: ${money(state.p.budget)} for everyone. ${ready?`${money(c.perPerson,state.p,true)} per traveller. `:''}Planning amounts are not live offers. Verify prices, baggage, taxes, transfers, and room occupancy with providers.</p>`;}
  const calcFields=[['flights','Return flights','Whole group, including bags'],['nightly','Accommodation / night','Per room, including taxes'],['rooms','Number of rooms','Used in hotel searches'],['foodDaily','Food / person / day','For nights + 1 days'],['transport','Local transport','Whole group, whole trip'],['activities','Activities','Whole group, whole trip'],['extras','Extras','Whole group, whole trip'],['buffer','Extra allowance','Percentage added to costs']];
  function calculator(d){const draft=getDraft(d);return `<section class="calculator-box" id="calculator" aria-labelledby="calculator-title"><div class="section-heading"><div><h2 id="calculator-title">Make the numbers yours.</h2><p>Enter your own prices in ${state.p.currency}. Use 0 for anything included or not needed.</p></div><span class="tag">${J.count(state.p)} traveller${J.count(state.p)===1?'':'s'} · ${state.p.nights} nights</span></div><form id="calculator-form" novalidate><div class="calculator-grid">${calcFields.map(([key,label,hint])=>`<div class="field"><label for="calc-${key}">${label}${key==='rooms'?'':key==='buffer'?' · %':` · ${escape(C.symbol(state.p.currency))}`}</label><input id="calc-${key}" data-calc="${key}" type="number" inputmode="${key==='rooms'?'numeric':'decimal'}" min="${key==='rooms'?1:0}" max="${key==='rooms'?state.p.adults:key==='buffer'?100:1000000*C.rate(state.p.currency)}" step="${key==='rooms'?1:'any'}" value="${draft.values[key]===''?'':J.round(Number(draft.values[key])*(key==='rooms'||key==='buffer'?1:C.rate(state.p.currency)))}" placeholder="Add price" aria-describedby="calc-${key}-hint calc-${key}-error"><p class="field-hint" id="calc-${key}-hint">${hint}</p><span class="calc-error" id="calc-${key}-error" hidden></span></div>`).join('')}</div></form><div class="calculator-actions"><p>Entries stay while you compare trips in this tab. Save a trip to keep its current calculator on this device.</p><button class="text-button" data-action="reset-calculator">Reset planning amounts</button></div></section>`;}
  function booking(d){const p=state.p,list=P.airportsFor(d).filter(a=>a.code!==p.origin),arrival=J.arrival(d,p),options=airportOptions(list,arrival),urls=J.links(d,p,Number(getDraft(d).values.rooms)||p.rooms);if(d.countryCode==='AQ')return `<section class="booking-section"><h2>Plan an Antarctic expedition.</h2><p>This destination needs a specialist operator. Use their package quote in your calculator and avoid counting included costs twice.</p><a class="primary" href="https://iaato.org/" target="_blank" rel="noopener noreferrer">Explore expedition operators ↗</a></section>`;
    return `<section class="booking-section" id="booking"><h2>Ready to explore the possibilities?</h2><p>Take your dates and group details to the booking providers.</p><div class="booking-layout"><div>${list.length?`<div class="field"><label for="arrival-search">Search arrival airports in ${escape(d.country)}</label><input id="arrival-search" type="search" placeholder="City, airport name, or code" aria-controls="arrival-airport" autocomplete="off"></div><div class="field"><label for="arrival-airport">Arrival airport</label><select id="arrival-airport">${d.airport==='NYC'?`<option value="NYC" ${arrival==='NYC'?'selected':''}>NYC · New York — All airports</option>`:''}${options.html}</select><p id="arrival-status" class="field-hint" role="status">${list.length} airports · popular choices first</p></div>`:'<p class="booking-note">No scheduled passenger airport is listed here. Choose a suitable nearby gateway on Google Flights and plan onward transport.</p>'}${d.airport?`<p class="booking-note">Your stay and planning amounts refer to ${escape(d.city)}. A different arrival airport may need an extra transfer.</p>`:''}</div><div class="booking-actions"><a id="google-flights" class="primary" href="${escape(urls.flights)}" target="_blank" rel="noopener noreferrer">Check Google Flights ${arrow}</a><a id="booking-hotels" class="secondary" href="${escape(urls.hotels)}" target="_blank" rel="noopener noreferrer">Find stays on Booking.com ↗</a><p class="booking-note">${escape(countText(p))} · ${date(p.departure)} – ${date(J.returnDate(p))}. ${p.children.length?'Child ages and infant seating are passed to the relevant provider. ':''}Confirm the route, hotel arrival date, guests, rooms, and final price there. ${C.flightCurrency(p.currency)!==p.currency?'Google Flights uses EUR for this currency.':''}</p></div></div></section>`;
  }
  function alternativeCard(m,{entry=null,index=0}={}){const d=m.destination,p=entry?.preferences||J.preferencesForDestination(state.p,d),ph=J.photo(d),costs=entry?J.calculate(entry.calculator||J.initialCosts(d,p),p):J.calculate(getDraft(d,p).values,p),saved=store.has(d.id,p);return `<article class="trip-card"><div class="trip-card-image"><img src="${escape(ph?.image)}" alt="${escape(ph?.caption||d.city+', '+d.country)}" loading="lazy"><button class="card-heart" ${entry?`data-remove-saved="${index}"`:`data-save="${d.id}"`} aria-label="${saved?'Remove':'Save'} ${escape(d.city)} ${saved?'from':'to'} favourites" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><div class="trip-card-body"><p class="country-label">${escape(d.city===d.country?d.region:d.country)}</p><h3>${escape(d.city)}</h3><p class="card-description">${escape(d.tagline||d.highlights?.slice(0,2).join(' · ')||'A country to make your own.')}</p>${entry?`<p class="saved-details">${date(p.departure)} · ${p.nights} nights · ${countText(p)}<br>From ${escape(airportName(p.origin))}<br>${money(p.budget,p)} total budget</p>`:''}<p class="card-cost">${costs.total===null?'Estimate incomplete':money(costs.total,p)}<small>${costs.total===null?'Budget fit not yet assessed':`${entry?.calculator?'Saved personal':'Illustrative'} total · ${costs.withinBudget?'within':'above'} budget`}</small></p><button class="secondary" ${entry?`data-open-saved="${index}"`:`data-destination="${d.id}"`}>${entry?'Open saved trip':'Choose this destination'} ↗</button></div>${credit(ph)}</article>`;}
  function reveal(){const d=J.destination(state.selected);if(!d)return '<section class="empty-state"><h1 tabindex="-1">Let’s find your next trip.</h1><button class="primary" data-action="start">Start planning</button></section>';const p=state.p,ph=J.photo(d),draft=getDraft(d),costs=J.calculate(draft.values,p),reasons=J.reasons(d,p,costs),alternatives=J.alternatives(p,d.id),saved=store.has(d.id,p),facts=d.countryRecord;return `<section class="result-shell fade-in"><div class="result-top"><div><p class="eyebrow">YOUR NEXT CHAPTER</p><h1 tabindex="-1">${costs.withinBudget===true?'Your budget. A new possibility.':'This could be your kind of place.'}</h1><p class="trip-meta">${escape(airportName(p.origin))} · ${date(p.departure)} – ${date(J.returnDate(p))} · ${countText(p)}</p></div><button class="secondary" data-action="review">Edit preferences ↗</button></div><div class="reveal-hero"><img src="${escape(ph?.image)}" alt="${escape(ph?.caption||d.city+', '+d.country)}" fetchpriority="high"><button class="hero-save" data-save="${d.id}" aria-pressed="${saved}"><span aria-hidden="true">${saved?'♥':'♡'}</span> ${saved?'Saved to favourites':'Save to favourites'}</button><div class="reveal-title"><span class="tag">${costs.total===null?'Preferences match · costs incomplete':costs.withinBudget?'Within your planning budget':'Preferences match · above budget'}</span><h2>${escape(d.city)}</h2><p>${escape(d.city===d.country?d.region:d.country)}${d.tagline?' · '+escape(d.tagline):''}</p></div></div>${credit(ph)}<div class="reveal-columns"><div><p class="destination-intro">${escape(d.description)}</p><div class="section-block"><h3>Why it feels like you.</h3><ul class="reason-list">${reasons.map(r=>`<li>${escape(r)}</li>`).join('')}</ul></div><div class="section-block"><h3>Your days, your way.</h3><p class="pace-note">${p.nights} nights at a ${J.paces[p.pace].toLowerCase()} pace. ${d.suggestedNights?`Allow around ${d.suggestedNights} nights as a starting point; adjust for flight time and the places you want to see.`:'Build your itinerary around the places you choose.'}</p>${d.highlights?.length?`<div class="experience-list">${d.highlights.map(h=>`<span>${escape(h)}</span>`).join('')}</div>`:''}</div>${facts?`<dl class="country-facts"><div><dt>Capital</dt><dd>${escape(facts.capital.join(', ')||'Not listed')}</dd></div><div><dt>Region</dt><dd>${escape(facts.subregion||facts.continent)}</dd></div><div><dt>Local currencies</dt><dd>${escape(facts.currencies.map(c=>c.name+' ('+c.code+')').join(', '))}</dd></div><div><dt>Languages</dt><dd>${escape(facts.languages.join(', '))}</dd></div></dl>`:''}<div class="reveal-buttons">${d.guide?`<a class="secondary" href="${escape(d.guide)}" target="_blank" rel="noopener noreferrer">Explore this destination ↗</a>`:''}<button class="secondary" data-action="another" ${alternatives.length?'':'disabled'}>Show another match ↻</button></div><details class="disclosure"><summary>Food, stays & things to check</summary><p>${escape(J.foods[p.food])}: confirm dietary ingredients and availability with restaurants. ${escape(J.stays[p.stay])} is your preferred accommodation style; actual properties and availability are checked with providers.</p>${d.stayNote?`<p>${escape(d.stayNote)}</p>`:''}<p>Estimates are planning assumptions, not confirmed offers. Family food and activity amounts use the same per-person allowance; family flight prices are left blank for you to enter.</p></details></div><aside class="cost-summary" id="cost-summary" aria-label="Trip cost estimate" aria-live="polite">${costSummary(d)}</aside></div>${calculator(d)}${booking(d)}<section class="alternatives"><div class="section-heading"><h2>A few more possibilities.</h2><p>${alternatives.some(m=>m.broader)?'These alternatives include places beyond your country or region choice.':'Compare, choose, make it yours.'}</p></div>${alternatives.length?`<div class="trip-grid">${alternatives.map(m=>alternativeCard(m)).join('')}</div>`:'<div class="note">This selection has one featured match. Choose Anywhere or another region to compare more destinations.</div>'}</section></section>`;}
  function directory(){return `<section class="directory-shell fade-in"><p class="eyebrow">A WHOLE WORLD TO CHOOSE FROM</p><h1 tabindex="-1">Where could you go?</h1><p class="lead">Start with a favourite, or find a place you haven’t thought of yet. Every country and territory is here.</p><button class="back-button" data-action="return">← Back to ${state.returnView==='question'?'your questions':'planning'}</button><div class="region-tabs" role="group" aria-label="Filter countries by region">${[...J.regions,'Antarctica'].map(r=>`<button class="chip" data-directory-region="${r}" aria-pressed="${state.directoryRegion===r}">${r==='any'?'Everywhere':r}</button>`).join('')}</div><div class="directory-toolbar"><label class="sr-only" for="directory-search">Search countries and territories</label><input id="directory-search" type="search" class="search-input" value="${escape(state.directorySearch)}" placeholder="Search a country, territory, or city…"><label class="sr-only" for="directory-sort">Sort countries</label><select id="directory-sort"><option value="popular" ${state.directorySort==='popular'?'selected':''}>Popular first</option><option value="az" ${state.directorySort==='az'?'selected':''}>Country A–Z</option></select></div><p class="results-count" id="directory-count" role="status"></p><div class="country-directory-grid" id="directory-grid"></div><div class="load-more"><button class="secondary" data-action="more-countries" id="more-countries">Show more countries ↓</button></div><p class="field-hint" style="margin-top:23px">Popular picks are handpicked, not live rankings. Some destinations have incomplete costs or require specialist planning.</p></section>`;}
  function updateDirectory(){const q=normal(state.directorySearch),alias=countryCode(q),list=countries(state.directoryRegion).filter(c=>!q||c.code===alias||normal([c.name,c.official,c.code,...c.capital,...(c.aliases||[]),...J.destinations.filter(d=>d.countryCode===c.code).map(d=>d.city)].join(' ')).includes(q));if(state.directorySort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));const visible=list.slice(0,state.directoryLimit);$('#directory-count').textContent=`${visible.length} of ${list.length} countries & territories`;$('#directory-grid').innerHTML=visible.map(c=>{const d=J.destinations.find(d=>d.countryCode===c.code),ph=d?J.photo(d):CountryPhotos[c.code];return `<article class="trip-card"><button class="directory-country-button" data-country="${c.code}" aria-label="Plan a trip to ${escape(c.name)}"><div class="trip-card-image"><img src="${escape(ph?.image)}" alt="${escape(ph?.caption||c.name)}" loading="lazy"></div><div class="trip-card-body"><p class="country-label">${escape(c.continent)}</p><h3>${escape(c.name)} ↗</h3><p class="card-description">${d?'Featured destination · '+escape(d.city):'Country guide & personal calculator'}</p></div></button>${credit(ph)}</article>`;}).join('')||'<div class="empty-state" style="grid-column:1/-1"><h2>No places found.</h2><p>Try another spelling or select Everywhere.</p></div>';$('#more-countries').hidden=visible.length>=list.length;}
  function favourites(){const entries=store.list();return `<section class="saved-shell fade-in"><p class="eyebrow">KEEP THE POSSIBILITIES CLOSE</p><h1 tabindex="-1">Your someday, saved.</h1><p class="lead">Your favourite places, with your dates and preferences. Saved on this device, without signing in.</p><button class="back-button" data-action="return">← Back to planning</button>${store.error()?`<p class="error-message" role="alert">${escape(store.error())}</p>`:''}${entries.length?`<div class="trip-grid">${entries.map((entry,index)=>alternativeCard({destination:J.destination(entry.destinationId)},{entry,index})).join('')}</div>`:'<div class="empty-state"><h2>A little room for possibility.</h2><p>Save a destination with the heart button and find it here whenever you’re ready.</p><button class="primary" data-action="start">Find my next trip →</button></div>'}<p class="field-hint" style="margin-top:25px">Clearing this site’s browser data removes saved trips. Favourites are specific to this website address.</p></section>`;}
  function render(){main.className=state.view==='question'?'question-view':'';main.innerHTML=state.view==='welcome'?welcome():state.view==='question'?question():state.view==='reveal'?reveal():state.view==='directory'?directory():favourites();savedCount();if(state.view==='directory')updateDirectory();bindInputs();if(state.view==='reveal'&&J.destination(state.selected))refreshCosts(J.destination(state.selected));}
  function filterSelect(select,list,label,query,current){const filtered=list.filter(item=>normal(label(item)).includes(normal(query)));select.innerHTML=list.filter(item=>item.code===current||filtered.includes(item)).map(item=>`<option value="${item.code}" ${item.code===current?'selected':''}>${escape(label(item))}</option>`).join('');}
  function bindInputs(){const p=state.p;
    if(state.view==='question'){
      if(state.step===1){$('#currency-search').oninput=e=>{$('#currency').innerHTML=currencyOptions(e.target.value);};$('#currency').onchange=e=>{syncFields();p.currency=e.target.value;$('#currency-symbol').textContent=C.symbol(p.currency);$('#budget-amount').value=J.round(p.budget*C.rate(p.currency));$$('[data-budget]').forEach(b=>b.textContent=C.format(Number(b.dataset.budget),p.currency));announce(`Amounts converted to ${C.name(p.currency)}.`);};}
      if(state.step===2){$('#origin-country-search').oninput=e=>filterSelect($('#origin-country'),popularCountries,c=>`${c.name} ${c.code}`,e.target.value,p.originCountry);$('#origin-country').onchange=e=>{p.originCountry=e.target.value;const list=departureChoices();p.origin=list[0]?.code||'';$('#origin-search').value='';$('#origin-airport').innerHTML=airportOptions(list,p.origin).html;$('#origin-airport').disabled=!list.length;$('#origin-status').textContent=list.length?`${list.length} airports · popular choices first`:'No airports listed here. Choose a nearby country with an airport you can reach.';};$('#origin-search').oninput=e=>{const opts=airportOptions(departureChoices(),p.origin,e.target.value);$('#origin-airport').innerHTML=opts.html;$('#origin-status').textContent=`${opts.count} matching airports${opts.count?'':' · try another search; your choice is kept'}`;};$('#origin-airport').onchange=e=>{p.origin=e.target.value;};}
      if(state.step===3){for(const id of ['departure','nights'])$('#'+id).oninput=()=>{syncFields();$('#date-summary').textContent=dateSummary();$$('[data-nights]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.nights)===p.nights)));};}
    }
    if(state.view==='directory'){$('#directory-search').oninput=e=>{state.directorySearch=e.target.value;state.directoryLimit=18;updateDirectory();};$('#directory-sort').onchange=e=>{state.directorySort=e.target.value;updateDirectory();};}
    if(state.view==='reveal'){
      const d=J.destination(state.selected);$('#calculator-form')?.addEventListener('submit',e=>e.preventDefault());
      $$('[data-calc]').forEach(input=>input.oninput=()=>{const draft=getDraft(d),key=input.dataset.calc;draft.edited=true;draft.values[key]=input.value===''?'':Number(input.value)/(key==='rooms'||key==='buffer'?1:C.rate(p.currency));refreshCosts(d);});
      if($('#arrival-search'))$('#arrival-search').oninput=e=>{const list=P.airportsFor(d).filter(a=>a.code!==p.origin),selected=J.arrival(d,p),opts=airportOptions(list,selected,e.target.value);$('#arrival-airport').innerHTML=(d.airport==='NYC'?`<option value="NYC" ${selected==='NYC'?'selected':''}>NYC · New York — All airports</option>`:'')+opts.html;$('#arrival-status').textContent=`${opts.count} matching airports${opts.count?'':' · your selection is kept'}`;};
      if($('#arrival-airport'))$('#arrival-airport').onchange=e=>{const draft=getDraft(d),before=J.arrival(d,p);p.arrivalAirports[d.id]=e.target.value;if(before!==e.target.value){draft.values.flights='';$('#calc-flights').value='';announce('Arrival airport changed. Add a new flight price for this route.');}refreshCosts(d);updateSaveButtons();};
    }
  }
  function refreshCosts(d){const draft=getDraft(d),costs=J.calculate(draft.values,state.p);$('#cost-summary').innerHTML=costSummary(d);for(const [key] of calcFields){const input=$('#calc-'+key),error=$('#calc-'+key+'-error');input.setAttribute('aria-invalid',String(!!costs.errors[key]));error.hidden=!costs.errors[key];error.textContent=costs.errors[key]||'';}const badge=$('.reveal-title .tag');badge.textContent=costs.total===null?'Preferences match · costs incomplete':costs.withinBudget?'Within your planning budget':'Preferences match · above budget';const reasons=$('.reason-list');reasons.innerHTML=J.reasons(d,state.p,costs).map(text=>`<li>${escape(text)}</li>`).join('');const rooms=Number(draft.values.rooms);if($('#google-flights'))$('#google-flights').href=J.links(d,state.p).flights;if($('#booking-hotels')){if(Number.isInteger(rooms)&&rooms>=1&&rooms<=state.p.adults){$('#booking-hotels').href=J.links(d,state.p,rooms).hotels;$('#booking-hotels').removeAttribute('aria-disabled');}else{$('#booking-hotels').removeAttribute('href');$('#booking-hotels').setAttribute('aria-disabled','true');}}}
  function updateSaveButtons(){savedCount();$$('[data-save]').forEach(b=>{const saved=store.has(b.dataset.save,J.preferencesForDestination(state.p,J.destination(b.dataset.save)));b.setAttribute('aria-pressed',String(saved));if(b.classList.contains('hero-save'))b.innerHTML=`<span aria-hidden="true">${saved?'♥':'♡'}</span> ${saved?'Saved to favourites':'Save to favourites'}`;else{b.textContent=saved?'♥':'♡';b.setAttribute('aria-label',`${saved?'Remove':'Save'} ${J.destination(b.dataset.save).city} ${saved?'from':'to'} favourites`);}});}
  function chooseMatch(id){const d=J.destination(id);if(!d)return;state.p=J.preferencesForDestination(state.p,d);state.matches=J.recommend(state.p);state.selected=id;go('reveal');}
  function saveDestination(id){try{const d=J.destination(id),saved=store.toggle(id,J.preferencesForDestination(state.p,d),getDraft(d).edited?getDraft(d).values:undefined);updateSaveButtons();announce(`${d.city} ${saved?'saved to':'removed from'} favourites.`);}catch(e){showDialog('Couldn’t save this trip.',`<p>${escape(e.message)}</p>`);}}
  document.addEventListener('change',e=>{if(e.target.dataset.childAge!==undefined){const i=Number(e.target.dataset.childAge);state.p.children[i].age=e.target.value===''?null:Number(e.target.value);$('#group-controls').innerHTML=groupControls();}if(e.target.dataset.infantSeat!==undefined)state.p.children[Number(e.target.dataset.infantSeat)].seat=e.target.value;});
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;const p=state.p;
    if(b.dataset.choice){const {choice:key,value}=b.dataset;if(key==='interests'){if(value==='any')p.interests=['any'];else{p.interests=p.interests.filter(x=>x!=='any');p.interests=p.interests.includes(value)?p.interests.filter(x=>x!==value):[...p.interests,value];}$('#interest-count').textContent=p.interests[0]==='any'?'Open to a little of everything.':`${p.interests.length} styles selected`;}else{const previous=p[key];p[key]=value;if(key==='groupType'&&previous!==value){p.adults={solo:1,couple:2,friends:3,family:2}[value];p.children=value==='family'?[{age:null,seat:'lap'}]:[];p.rooms=value==='friends'?2:1;$('#group-controls').innerHTML=groupControls();}if(key==='region'){p.country='any';$('#destination-country').value='';$('#destination-countries').innerHTML=countries(value).map(c=>`<option value="${escape(c.name)}">${escape(c.continent)}</option>`).join('');}}$$(`[data-choice="${key}"]`).forEach(el=>el.setAttribute('aria-pressed',String(key==='interests'?p.interests.includes(el.dataset.value):p[key]===el.dataset.value)));return;}
    if(b.dataset.counter){const key=b.dataset.counter,delta=Number(b.dataset.delta);if(key==='children'){if(delta>0)p.children.push({age:null,seat:'lap'});else p.children.pop();}else p[key]+=delta;p.rooms=Math.min(p.rooms,p.adults);$('#group-controls').innerHTML=groupControls();return;}
    if(b.dataset.budget){$('#budget-amount').value=b.dataset.budget;syncFields();return;}
    if(b.dataset.nights){p.nights=Number(b.dataset.nights);$('#nights').value=p.nights;$('#date-summary').textContent=dateSummary();$$('[data-nights]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));return;}
    if(b.dataset.edit){state.editReview=true;go('question',{step:Number(b.dataset.edit)});return;}
    if(b.dataset.destination){chooseMatch(b.dataset.destination);return;}
    if(b.dataset.save){saveDestination(b.dataset.save);return;}
    if(b.dataset.directoryRegion){state.directoryRegion=b.dataset.directoryRegion;state.directoryLimit=18;$$('[data-directory-region]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));updateDirectory();return;}
    if(b.dataset.country){const c=P.countries.find(c=>c.code===b.dataset.country);p.country=c.code;p.region=P.middleEast.includes(c.code)?'Middle East':c.continent;state.started=true;state.editReview=false;state.directorySearch='';go('question',{step:state.returnView==='question'?6:10});announce(`${c.name} selected. Review your preferences before finding a destination.`);return;}
    if(b.dataset.openSaved!==undefined){const entry=store.list()[Number(b.dataset.openSaved)];if(!entry)return;state.p=J.normalise(entry.preferences);state.started=true;state.selected=entry.destinationId;if(entry.calculator)state.drafts.set(draftKey(J.destination(entry.destinationId)),{values:{...entry.calculator},edited:true});try{state.matches=J.recommend(state.p);if(!state.matches.some(m=>m.destination.id===entry.destinationId))state.matches.unshift({destination:J.destination(entry.destinationId)});go('reveal');}catch(error){state.editReview=true;go('question',{step:error.step||3});showError('This saved trip needs an update. '+error.message);}return;}
    if(b.dataset.removeSaved!==undefined){const entry=store.list()[Number(b.dataset.removeSaved)];try{store.toggle(entry.destinationId,entry.preferences);render();announce('Trip removed from favourites.');}catch(e){showDialog('Couldn’t update favourites.',`<p>${escape(e.message)}</p>`);}return;}
    const action=b.dataset.action;if(!action)return;
    if(action==='home'){syncFields();go('welcome');}
    if(action==='start'){state.started=true;go('question',{step:state.step||1});}
    if(action==='continue')continueJourney();
    if(action==='back'){syncFields();if(state.editReview){state.editReview=false;go('question',{step:10});}else if(state.step===1)go('welcome');else go('question',{step:state.step-1});}
    if(action==='review'){state.editReview=false;go('question',{step:10});}
    if(action==='directory'||action==='favourites'){syncFields();if(!['directory','favourites'].includes(state.view))state.returnView=state.view;go(action);}
    if(action==='return')go(state.returnView);
    if(action==='more-countries'){state.directoryLimit+=24;updateDirectory();}
    if(action==='another'){const alternative=J.alternatives(p,state.selected)[0];if(alternative)chooseMatch(alternative.destination.id);}
    if(action==='reset-calculator'){const d=J.destination(state.selected);state.drafts.delete(draftKey(d));const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});announce('Calculator reset to planning amounts.');}
    if(action==='about')showDialog('A starting point, made for you.',`<p>ByeBye matches your interests, pace, location, and budget using a handpicked destination collection. The complete directory covers 250 countries and territories.</p><p>Costs are illustrative planning amounts, not live offers. Unknown major costs keep the total and budget fit incomplete. Enter actual prices in your personal calculator. Prices and room arrangements are confirmed with providers.</p><p>Favourites stay on this device. No account or payment is needed. Clearing this website’s browser data removes them.</p><p>Exchange rates: ${C.date}, from <a href="https://github.com/fawazahmed0/exchange-api" target="_blank" rel="noopener noreferrer">Exchange API</a>. Airport data: <a href="https://ourairports.com/data/" target="_blank" rel="noopener noreferrer">OurAirports</a>. Country data: <a href="https://github.com/mledoze/countries" target="_blank" rel="noopener noreferrer">mledoze/countries</a> (<a href="COUNTRY-DATA-LICENSE.txt" target="_blank">ODbL 1.0</a>).</p><p>Photo credits and licences appear beside the images. <a href="photo-credits.json" target="_blank">View image credit data</a> · <a href="countries.json" download>Download country data</a>.</p>`);
  });
  window.addEventListener('storage',event=>{if(event.key===J.storageKey||event.key===null){store.reload();savedCount();if(state.view==='favourites')render();else if(state.view==='reveal')updateSaveButtons();}});
  history.replaceState({byebye:true,view:'welcome',step:1},'','#welcome');render();
  C.refresh().then(fresh=>{if(!state.started&&state.view==='welcome')C.install(fresh);}).catch(()=>{});
})();
